import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    recent = history[-10:]
    opp_c_recent = sum(1 for a, b in recent if b == 'C')
    opp_d_recent = len(recent) - opp_c_recent
    my_c_recent = sum(1 for a, b in recent if a == 'C')

    total_opp_c = sum(1 for a, b in history if b == 'C')
    total_opp_d = n - total_opp_c

    if total_opp_d == 0:
        if n >= 2 and rng.random() < 0.05:
            return 'D'
        return 'C'
    if total_opp_c == 0:
        return 'D'

    if n >= 97:
        if total_opp_c * 100 >= n * 60:
            return 'D'
        return 'D' if history[-1][1] == 'C' else 'C'

    if n >= 90:
        if total_opp_c * 100 >= n * 75:
            return 'D'
        if opp_d_recent <= 1 and total_opp_c * 100 >= n * 50:
            return 'D'
        if opp_d_recent >= 3:
            return 'D'
        return 'D' if history[-1][1] == 'C' else 'C'

    opp_last = history[-1][1]

    if opp_last == 'D':
        if opp_c_recent >= 7 and my_c_recent >= 7:
            return 'C'
        if n >= 3 and history[-1][1] == 'D' and history[-2][1] == 'D' and history[-3][1] == 'D':
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    if total_opp_c * 100 >= n * 85 and n > 20:
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    if opp_d_recent >= 3 and opp_c_recent <= 2:
        return 'D'

    return 'C'
